class stringx
{
  char data_[8];

public:
  ~stringx();
};

class material
{
public:
  ~material();
};

struct material_ref_t
{
  stringx label;
  material* ptr;
  unsigned int count;
};

struct tree_node
{
  int color;
  tree_node* parent;
  tree_node* left;
  tree_node* right;
  material_ref_t* value;
};

class tree_iterator
{
public:
  tree_node* node;

  material_ref_t*& operator*() const
  {
    return node->value;
  }

  tree_iterator& operator++()
  {
    if (node->right != 0)
    {
      node = node->right;
      while (node->left != 0)
        node = node->left;
    }
    else
    {
      tree_node* parent = node->parent;
      while (node == parent->right)
      {
        node = parent;
        parent = parent->parent;
      }
      if (node->right != parent)
        node = parent;
    }
    return *this;
  }

  bool operator!=(const tree_iterator& other) const
  {
    return node != other.node;
  }
};

class lref_set
{
public:
  typedef tree_iterator iterator;
  tree_node* header;
  unsigned int node_count;
  unsigned int padding;

  iterator begin() const
  {
    iterator result = { header->left };
    return result;
  }

  iterator end() const
  {
    iterator result = { header };
    return result;
  }

  void clear();
};

class pref_set
{
public:
  tree_node* header;
  unsigned int node_count;
  unsigned int padding;

  void clear();
};

template <class T>
class instance_bank
{
public:
  typedef material_ref_t ref_t;

  lref_set refs_by_label;
  pref_set refs_by_ptr;

  void purge();
};

