void lref_set::clear()
{
  if (node_count != 0)
  {
    erase_label(this, header->parent);
    header->left = header;
    header->parent = 0;
    header->right = header;
    node_count = 0;
  }
}

void pref_set::clear()
{
  if (node_count != 0)
  {
    erase_ptr(this, header->parent);
    header->left = header;
    header->parent = 0;
    header->right = header;
    node_count = 0;
  }
}

template <class T>
void instance_bank<T>::purge()
{
  lref_set::iterator i = refs_by_label.begin();
  lref_set::iterator i_end = refs_by_label.end();

  while(i != i_end)
  {
    lref_set::iterator del = i;
    ++i;

    delete (*del)->ptr;
    delete *del;
  }

  refs_by_label.clear();
  refs_by_ptr.clear();
}

